The supplied files need changes to declare and implement `convert`. The implementation validates bases and digits, then performs positional conversion manually without relying on library conversion routines. It also normalizes leading zeroes to a single zero digit.

all_your_base.h
```
#if !defined(ALL_YOUR_BASE_H)
#define ALL_YOUR_BASE_H

#include <vector>

namespace all_your_base {

std::vector<unsigned> convert(const std::vector<unsigned>& digits,
                              unsigned input_base,
                              unsigned output_base);

}  // namespace all_your_base

#endif  // ALL_YOUR_BASE_H
```

all_your_base.cpp
```
#include "all_your_base.h"

#include <cstdint>

namespace all_your_base {

std::vector<unsigned> convert(const std::vector<unsigned>& digits,
                              unsigned input_base,
                              unsigned output_base) {
    if (input_base < 2 || output_base < 2) {
        return {};
    }

    for (unsigned digit : digits) {
        if (digit >= input_base) {
            return {};
        }
    }

    std::vector<unsigned> result;

    for (unsigned digit : digits) {
        std::uint64_t carry = digit;

        for (auto position = result.rbegin(); position != result.rend();
             ++position) {
            const std::uint64_t value =
                static_cast<std::uint64_t>(*position) * input_base + carry;

            *position = static_cast<unsigned>(value % output_base);
            carry = value / output_base;
        }

        while (carry != 0) {
            result.insert(
                result.begin(),
                static_cast<unsigned>(carry % output_base));
            carry /= output_base;
        }
    }

    if (result.empty()) {
        result.push_back(0);
    }

    return result;
}

}  // namespace all_your_base
```

