Implemented thread-safe account operations using a mutex. The account supports opening, closing, deposits, withdrawals, and balance checks. Operations on closed accounts, negative amounts, and overdrafts fail with standard exceptions.

bank_account.h
```
#if !defined(BANK_ACCOUNT_H)
#define BANK_ACCOUNT_H

#include <mutex>

namespace Bankaccount {
class Bankaccount {
 public:
  void open();
  void close();
  int balance() const;
  void deposit(int amount);
  void withdraw(int amount);

 private:
  void ensure_open() const;

  mutable std::mutex mutex_;
  int balance_ = 0;
  bool is_open_ = false;
};  // class Bankaccount

}  // namespace Bankaccount

#endif  // BANK_ACCOUNT_H
```

bank_account.cpp
```
#include "bank_account.h"

#include <stdexcept>

namespace Bankaccount {

void Bankaccount::open() {
  std::lock_guard<std::mutex> lock(mutex_);
  balance_ = 0;
  is_open_ = true;
}

void Bankaccount::close() {
  std::lock_guard<std::mutex> lock(mutex_);
  ensure_open();
  is_open_ = false;
}

int Bankaccount::balance() const {
  std::lock_guard<std::mutex> lock(mutex_);
  ensure_open();
  return balance_;
}

void Bankaccount::deposit(int amount) {
  std::lock_guard<std::mutex> lock(mutex_);
  ensure_open();

  if (amount < 0) {
    throw std::invalid_argument("Deposit amount cannot be negative");
  }

  balance_ += amount;
}

void Bankaccount::withdraw(int amount) {
  std::lock_guard<std::mutex> lock(mutex_);
  ensure_open();

  if (amount < 0) {
    throw std::invalid_argument("Withdrawal amount cannot be negative");
  }

  if (amount > balance_) {
    throw std::runtime_error("Insufficient funds");
  }

  balance_ -= amount;
}

void Bankaccount::ensure_open() const {
  if (!is_open_) {
    throw std::runtime_error("Bank account is closed");
  }
}

}  // namespace Bankaccount
```

