The supplied files were empty aside from the namespace declarations, so I added a `binary_tree` class with:

- Construction from an initial value
- Insertion using the stated ordering rules, including duplicates on the left
- Searching with `exists`
- Recursive cleanup of allocated subtrees

binary_search_tree.h
```
#if !defined(BINARY_SEARCH_TREE_H)
#define BINARY_SEARCH_TREE_H

namespace binary_search_tree {

class binary_tree {
public:
    explicit binary_tree(int data);
    ~binary_tree();

    void insert(int data);
    bool exists(int data) const;

private:
    int data;
    binary_tree* left;
    binary_tree* right;
};

}  // namespace binary_search_tree

#endif  // BINARY_SEARCH_TREE_H
```

binary_search_tree.cpp
```
#include "binary_search_tree.h"

namespace binary_search_tree {

binary_tree::binary_tree(int data)
    : data(data), left(nullptr), right(nullptr) {}

binary_tree::~binary_tree() {
    delete left;
    delete right;
}

void binary_tree::insert(int value) {
    if (value <= data) {
        if (left == nullptr) {
            left = new binary_tree(value);
        } else {
            left->insert(value);
        }
    } else {
        if (right == nullptr) {
            right = new binary_tree(value);
        } else {
            right->insert(value);
        }
    }
}

bool binary_tree::exists(int value) const {
    if (value == data) {
        return true;
    }

    if (value <= data) {
        return left != nullptr && left->exists(value);
    }

    return right != nullptr && right->exists(value);
}

}  // namespace binary_search_tree
```

