namespace crypto_square {

std::string cipher(const std::string& input) {
    std::string normalized;

    for (unsigned char character : input) {
        if (std::isalnum(character)) {
            normalized += static_cast<char>(std::tolower(character));
        }
    }

    if (normalized.empty()) {
        return "";
    }

    const std::size_t columns =
        static_cast<std::size_t>(std::ceil(std::sqrt(normalized.size())));
    const std::size_t rows =
        (normalized.size() + columns - 1) / columns;

    std::string encoded;

    for (std::size_t column = 0; column < columns; ++column) {
        if (column > 0) {
            encoded += ' ';
        }

        for (std::size_t row = 0; row < rows; ++row) {
            const std::size_t index = row * columns + column;
            if (index < normalized.size()) {
                encoded += normalized[index];
            } else {
                encoded += ' ';
            }
        }
    }

    return encoded;
}

}  // namespace crypto_square
