messages.content:
Implemented parallel letter-frequency counting using standard C++ threads. The implementation:

- Splits the input texts across up to `workers` threads.
- Counts letters case-insensitively.
- Ignores non-letter characters.
- Safely handles empty input and zero workers.
- Merges each thread’s local frequency map into the final result.

parallel_letter_frequency.h
```
#if !defined(PARALLEL_LETTER_FREQUENCY_H)
#define PARALLEL_LETTER_FREQUENCY_H

#include <map>
#include <string>
#include <vector>

namespace parallel_letter_frequency {

using frequency = std::map<char, int>;

frequency count(const std::vector<std::string>& texts, unsigned int workers);

}

#endif
```

parallel_letter_frequency.cpp
```
#include "parallel_letter_frequency.h"

#include <algorithm>
#include <cctype>
#include <thread>
#include <vector>

namespace parallel_letter_frequency {

frequency count(const std::vector<std::string>& texts, unsigned int workers)
{
    frequency result;

    if (texts.empty()) {
        return result;
    }

    const auto worker_count = std::max<std::size_t>(
        1,
        std::min<std::size_t>(workers, texts.size()));

    const auto texts_per_worker = texts.size() / worker_count;
    const auto extra_texts = texts.size() % worker_count;

    std::vector<frequency> partial_frequencies(worker_count);
    std::vector<std::thread> threads;
    threads.reserve(worker_count);

    std::size_t begin = 0;

    for (std::size_t worker = 0; worker < worker_count; ++worker) {
        const auto text_count = texts_per_worker + (worker < extra_texts ? 1 : 0);
        const auto end = begin + text_count;

        threads.emplace_back([&texts, &partial_frequencies, begin, end, worker] {
            auto& local_frequency = partial_frequencies[worker];

            for (std::size_t text_index = begin; text_index < end; ++text_index) {
                for (const auto character : texts[text_index]) {
                    const auto unsigned_character =
                        static_cast<unsigned char>(character);

                    if (std::isalpha(unsigned_character)) {
                        const auto lowercase_character = static_cast<char>(
                            std::tolower(unsigned_character));
                        ++local_frequency[lowercase_character];
                    }
                }
            }
        });

        begin = end;
    }

    for (auto& thread : threads) {
        thread.join();
    }

    for (const auto& partial_frequency : partial_frequencies) {
        for (const auto& [character, frequency_count] : partial_frequency) {
            result[character] += frequency_count;
        }
    }

    return result;
}

}
