#include "sublist.h"

#include <algorithm>

namespace sublist {

namespace {

bool contains(const std::vector<int>& list, const std::vector<int>& sublist) {
    return std::search(list.begin(), list.end(),
                       sublist.begin(), sublist.end()) != list.end() ||
           sublist.empty();
}

}  // namespace

Relation check_lists(const std::vector<int>& list_one,
                    const std::vector<int>& list_two) {
    if (list_one == list_two) {
        return Relation::equal;
    }

    if (contains(list_one, list_two)) {
        return Relation::superlist;
    }

    if (contains(list_two, list_one)) {
        return Relation::sublist;
    }

    return Relation::unequal;
}

}  // namespace sublist
