namespace phone_number {

std::string clean(const std::string& number) {
    std::string digits;

    for (const unsigned char character : number) {
        if (std::isdigit(character)) {
            digits += static_cast<char>(character);
        } else if (!std::isspace(character) && !std::ispunct(character)) {
            throw std::domain_error("Invalid phone number");
        }
    }

    if (digits.size() == 11) {
        if (digits.front() != '1') {
            throw std::domain_error("Invalid country code");
        }
        digits.erase(digits.begin());
    }

    if (digits.size() != 10 ||
        digits[0] < '2' || digits[0] > '9' ||
        digits[3] < '2' || digits[3] > '9') {
        throw std::domain_error("Invalid phone number");
    }

    return digits;
}

}  // namespace phone_number
