#include "sublist.h"

#include <algorithm>

namespace sublist {
namespace {

bool contains(const std::vector<int>& list, const std::vector<int>& sublist)
{
    if (sublist.empty()) {
        return true;
    }

    if (sublist.size() > list.size()) {
        return false;
    }

    return std::search(list.begin(), list.end(),
                       sublist.begin(), sublist.end()) != list.end();
}

}  // namespace

Comparison classify(const std::vector<int>& a, const std::vector<int>& b)
{
    if (a == b) {
        return Comparison::equal;
    }

    if (contains(a, b)) {
        return Comparison::superlist;
    }

    if (contains(b, a)) {
        return Comparison::sublist;
    }

    return Comparison::unequal;
}

}  // namespace sublist
