Implemented a binary search tree with:

- Construction from an initial value
- Insertion of additional values
- Search via `contains`
- Duplicate values placed in the left subtree, following the specification
- Recursive cleanup of allocated nodes

binary_search_tree.h
```
#if !defined(BINARY_SEARCH_TREE_H)
#define BINARY_SEARCH_TREE_H

namespace binary_search_tree {

class tree {
public:
    explicit tree(int value);
    ~tree();

    void insert(int value);
    bool contains(int value) const;

private:
    struct node {
        explicit node(int value);

        int value;
        node* left;
        node* right;
    };

    node* root;

    static void destroy(node* current);
};

}  // namespace binary_search_tree

#endif  // BINARY_SEARCH_TREE_H
```

binary_search_tree.cpp
```
#include "binary_search_tree.h"

namespace binary_search_tree {

tree::node::node(int value)
    : value(value), left(nullptr), right(nullptr) {}

tree::tree(int value)
    : root(new node(value)) {}

tree::~tree() {
    destroy(root);
}

void tree::insert(int value) {
    node* current = root;

    while (true) {
        if (value <= current->value) {
            if (current->left == nullptr) {
                current->left = new node(value);
                return;
            }

            current = current->left;
        } else {
            if (current->right == nullptr) {
                current->right = new node(value);
                return;
            }

            current = current->right;
        }
    }
}

bool tree::contains(int value) const {
    const node* current = root;

    while (current != nullptr) {
        if (value == current->value) {
            return true;
        }

        if (value <= current->value) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    return false;
}

void tree::destroy(node* current) {
    if (current == nullptr) {
        return;
    }

    destroy(current->left);
    destroy(current->right);
    delete current;
}

}  // namespace binary_search_tree
