#include "crypto_square.h"

#include <cctype>
#include <string>

namespace crypto_square {

std::string cipher_text(std::string plaintext) {
    std::string normalized;
    normalized.reserve(plaintext.size());

    for (unsigned char character : plaintext) {
        if (std::isalnum(character)) {
            normalized += static_cast<char>(std::tolower(character));
        }
    }

    if (normalized.empty()) {
        return {};
    }

    const std::size_t length = normalized.size();

    std::size_t columns = 1;
    std::size_t rows = length;

    while (true) {
        rows = (length + columns - 1) / columns;

        if (columns >= rows && columns - rows <= 1 &&
            rows * columns >= length) {
            break;
        }

        ++columns;
    }

    std::string result;
    result.reserve(columns * rows + columns - 1);

    for (std::size_t column = 0; column < columns; ++column) {
        if (column > 0) {
            result += ' ';
        }

        for (std::size_t row = 0; row < rows; ++row) {
            const std::size_t index = row * columns + column;

            if (index < length) {
                result += normalized[index];
            } else {
                result += ' ';
            }
        }
    }

    return result;
}

}  // namespace crypto_square
