#include "yacht.h"

#include <algorithm>
#include <array>
#include <numeric>

namespace yacht {

int score(std::array<int, 5> dice, category category) {
    std::array<int, 7> counts{};

    for (int die : dice) {
        ++counts[die];
    }

    switch (category) {
        case category::ones:
        case category::twos:
        case category::threes:
        case category::fours:
        case category::fives:
        case category::sixes: {
            const int face = static_cast<int>(category) + 1;
            return face * counts[face];
        }

        case category::full_house: {
            bool has_three = false;
            bool has_two = false;

            for (int count : counts) {
                has_three |= count == 3;
                has_two |= count == 2;
            }

            return has_three && has_two
                ? std::accumulate(dice.begin(), dice.end(), 0)
                : 0;
        }

        case category::four_of_a_kind:
            for (int face = 1; face <= 6; ++face) {
                if (counts[face] >= 4) {
                    return face * 4;
                }
            }
            return 0;

        case category::little_straight:
            return counts[1] == 1 && counts[2] == 1 && counts[3] == 1 &&
                           counts[4] == 1 && counts[5] == 1
                       ? 30
                       : 0;

        case category::big_straight:
            return counts[2] == 1 && counts[3] == 1 && counts[4] == 1 &&
                           counts[5] == 1 && counts[6] == 1
                       ? 30
                       : 0;

        case category::choice:
            return std::accumulate(dice.begin(), dice.end(), 0);

        case category::yacht:
            return std::any_of(counts.begin(), counts.end(),
                               [](int count) { return count == 5; })
                       ? 50
                       : 0;
    }

    return 0;
}

}  // namespace yacht
